S=/synthetic/repo/tmp/-synthetic-repo/00000000-0000-4000-8000-000000000002/scratchpad; mkdir -p $S; cat > $S/probes.ts <<'EOF'
import { readdirSync } from "fs";
const dir = "/synthetic/repo/plugin/adapters/_shared/src";
const root = process.argv[2];
let pass=0, fail=0, vac=0; const bad:string[]=[];
for (const f of readdirSync(dir).filter(f=>f.endsWith(".ts")&&!f.endsWith(".test.ts"))) {
  let m:any; try { m = await import(`${dir}/${f}`); } catch { continue; }
  for (const k of Object.keys(m).filter(k=>/^run.*Probe$/.test(k))) {
    try {
      const r:any = await m[k](root);
      const v = r?.violations ?? [];
      const errs = v.filter((x:any)=>(x.severity??"error")==="error");
      if (errs.length) { fail++; bad.push(`${k}: ${errs.map((x:any)=>x.note??x.message).join(" | ")}`); }
      else { pass++; if (r?.vacuous) vac++; }
      const notes = (r?.notes??[]).concat(v.filter((x:any)=>x.severity&&x.severity!=="error"));
      if (notes.length) console.log("NOTE", k, JSON.stringify(notes).slice(0,300));
    } catch(e:any) { bad.push(`${k}: threw ${e.message}`); fail++; }
  }
}
console.log({pass, fail, vac}); bad.forEach(b=>console.log("FAIL", b));
EOF
bun run $S/probes.ts "$PWD" 2>&1 | tail -30

